function validate([s, maxLetters, minSize, maxSize]) {
  if (typeof s !== 'string' || s.length < 1 || s.length > 1e5) return 's needs 1 to 10^5 letters.';
  if (!/^[a-z]+$/.test(s)) return 's contains only lowercase English letters.';
  if (!Number.isInteger(maxLetters) || maxLetters < 1 || maxLetters > 26) return 'maxLetters is from 1 to 26.';
  if (!Number.isInteger(minSize) || !Number.isInteger(maxSize) || minSize < 1 || minSize > maxSize) return 'Need 1 <= minSize <= maxSize.';
  if (maxSize > Math.min(26, s.length)) return 'maxSize is at most min(26, s.length).';
  return null;
}

