function maxFreq(s, maxLetters, minSize, maxSize) {
  const letters = new Map();
  const counts = new Map();
  let best = 0;

  for (let right = 0; right < s.length; right++) {
    const incoming = s[right];
    letters.set(incoming, (letters.get(incoming) ?? 0) + 1);
    const left = right - minSize + 1;
    if (left < 0) {
      continue;
    }
    if (letters.size <= maxLetters) {
      const word = s.slice(left, right + 1);
      const times = (counts.get(word) ?? 0) + 1;
      counts.set(word, times);
      best = Math.max(best, times);
    }
    const outgoing = s[left];
    if (letters.get(outgoing) === 1) {
      letters.delete(outgoing);
    } else {
      letters.set(outgoing, letters.get(outgoing) - 1);
    }
  }
  return best;
}

