function maxFreq(s, maxLetters, minSize, maxSize) {
  // Count every allowed substring of every allowed length.
  const tally = new Map();
  let answer = 0;
  for (let size = minSize; size <= maxSize; size++) {
    for (let start = 0; start + size <= s.length; start++) {
      const piece = s.substring(start, start + size);
      if (new Set(piece).size > maxLetters) continue;
      const times = (tally.get(piece) || 0) + 1;
      tally.set(piece, times);
      if (times > answer) answer = times;
    }
  }
  return answer;
}

