function generate(rand, size) {
  const pick = (low, high) => low + Math.floor(rand() * (high - low + 1));
  const alphabet = 'abcdefghijklmnopqrstuvwxyz';
  const kinds = size === 'large' ? (rand() < 0.5 ? pick(2, 4) : 26) : pick(1, 4);
  const length = size === 'large' ? pick(9000, 10000) : pick(1, 12);
  let s = '';
  for (let i = 0; i < length; i++) s += alphabet[Math.floor(rand() * kinds)];
  const cap = Math.min(26, length);
  const minSize = pick(1, size === 'large' ? Math.min(cap, 8) : cap);
  const maxSize = pick(minSize, cap);
  const maxLetters = size === 'large' ? pick(1, Math.min(26, kinds + 1)) : pick(1, 5);
  return [s, maxLetters, minSize, maxSize];
}
